solutionCode:
pub fn ate_tres() -> i32 {
    let mut conta = 0;
    loop {
        conta += 1;
        if conta == 3 {
            break;
        }
    }
    conta
}

pub fn soma_ate(limite: i32) -> i32 {
    let mut soma = 0;
    let mut n = 1;
    loop {
        if n > limite {
            break;
        }
        soma += n;
        n += 1;
    }
    soma
}

testsCode:
use desafio::soma_ate;

#[test]
fn testa_a_soma_ate_quatro() {
    assert_eq!(soma_ate(4), 10);
}

#[test]
fn testa_a_soma_ate_um() {
    assert_eq!(soma_ate(1), 1);
}

#[test]
fn testa_a_soma_ate_zero_nao_soma_nada() {
    assert_eq!(soma_ate(0), 0);
}
